package com.hotel.dao.impl;
import com.hotel.dao.FrontDeskDao;import com.hotel.dto.*;import java.math.BigDecimal;import java.sql.*;import java.time.*;import java.util.*;
public class FrontDeskDaoImpl implements FrontDeskDao{
 public Optional<AssignmentTargetDto> findAssignmentTarget(Connection c,long id,boolean lock)throws SQLException{String h=lock?" WITH (UPDLOCK,HOLDLOCK) ":" ";String q="SELECT rr.reservation_room_id,v.reservation_id,v.booking_code,cu.full_name,v.status_code,rr.room_type_id,rt.type_name,rr.quantity,(SELECT COUNT(*) FROM room_assignments a WHERE a.reservation_room_id=rr.reservation_room_id AND a.is_current=1 AND a.unassigned_at IS NULL),v.check_in_date,v.check_out_date FROM reservation_rooms rr"+h+"JOIN reservations v"+h+"ON v.reservation_id=rr.reservation_id JOIN customers cu ON cu.customer_id=v.customer_id JOIN room_types rt ON rt.room_type_id=rr.room_type_id WHERE rr.reservation_room_id=?";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new AssignmentTargetDto(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getLong(6),r.getString(7),r.getInt(8),r.getInt(9),r.getObject(10,LocalDate.class),r.getObject(11,LocalDate.class))):Optional.empty();}}}
 public Optional<RoomStateDto> findRoomState(Connection c,long id,boolean lock)throws SQLException{String h=lock?" WITH (UPDLOCK,HOLDLOCK) ":" ";String q="SELECT rm.room_id,rm.room_type_id,rm.room_number,rm.floor_number,rm.operational_status,rm.cleaning_status,rm.is_active,CASE WHEN EXISTS(SELECT 1 FROM room_assignments a WITH (UPDLOCK,HOLDLOCK) WHERE a.room_id=rm.room_id AND a.is_current=1 AND a.unassigned_at IS NULL) THEN 1 ELSE 0 END FROM rooms rm"+h+"WHERE rm.room_id=?";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();Number f=(Number)r.getObject(4);return Optional.of(new RoomStateDto(r.getLong(1),r.getLong(2),r.getString(3),f==null?null:f.intValue(),r.getString(5),r.getString(6),r.getBoolean(7),r.getBoolean(8)));}}}
 public List<AvailableRoomDto> findAvailableRooms(Connection c,long rrId)throws SQLException{String q="SELECT rm.room_id,rm.room_number,rm.floor_number,rt.type_code,rt.type_name,rt.bed_type,rt.max_adults,rt.max_children,rm.operational_status,rm.cleaning_status,v.check_in_date,v.check_out_date FROM reservation_rooms rr JOIN reservations v ON v.reservation_id=rr.reservation_id JOIN rooms rm ON rm.room_type_id=rr.room_type_id JOIN room_types rt ON rt.room_type_id=rm.room_type_id WHERE rr.reservation_room_id=? AND rm.is_active=1 AND rt.is_active=1 AND rm.operational_status='AVAILABLE' AND rm.cleaning_status='INSPECTED' AND NOT EXISTS(SELECT 1 FROM room_assignments a WHERE a.room_id=rm.room_id AND a.is_current=1 AND a.unassigned_at IS NULL) ORDER BY rm.floor_number,rm.room_number";List<AvailableRoomDto>x=new ArrayList<>();try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,rrId);try(ResultSet r=p.executeQuery()){while(r.next()){Number f=(Number)r.getObject(3);x.add(new AvailableRoomDto(r.getLong(1),r.getString(2),f==null?null:f.intValue(),r.getString(4),r.getString(5),r.getString(6),r.getInt(7),r.getInt(8),r.getString(9),r.getString(10),r.getObject(11,LocalDate.class),r.getObject(12,LocalDate.class)));}}}return x;}
 public void insertAssignment(Connection c,long rr,long room,long user)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO room_assignments(reservation_room_id,room_id,assigned_by_user_id,assigned_at,unassigned_at,unassigned_reason,is_current) VALUES(?,?,?,SYSUTCDATETIME(),NULL,NULL,1)")){p.setLong(1,rr);p.setLong(2,room);p.setLong(3,user);p.executeUpdate();}}
 public Optional<CheckInDto> findCheckIn(Connection c,String id,boolean lock)throws SQLException{String h=lock?" WITH (UPDLOCK,HOLDLOCK) ":" ";String q="SELECT v.reservation_id,v.booking_code,v.status_code,cu.customer_id,cu.full_name,CASE WHEN cu.status_code='ACTIVE' THEN 1 ELSE 0 END,v.check_in_date,v.check_out_date,CASE WHEN EXISTS(SELECT 1 FROM reservation_guests g WHERE g.reservation_id=v.reservation_id AND g.is_primary_guest=1) THEN 1 ELSE 0 END,CASE WHEN EXISTS(SELECT 1 FROM reservation_guests g WHERE g.reservation_id=v.reservation_id AND g.is_primary_guest=1 AND g.id_document_type IS NOT NULL AND g.id_document_number IS NOT NULL) THEN 1 ELSE 0 END,v.deposit_required,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.reservation_id=v.reservation_id AND p.payment_type='DEPOSIT' AND p.status_code='SUCCESS'),(SELECT COUNT(*) FROM room_assignments a JOIN reservation_rooms rr ON rr.reservation_room_id=a.reservation_room_id WHERE rr.reservation_id=v.reservation_id AND a.is_current=1 AND a.unassigned_at IS NULL) FROM reservations v"+h+"JOIN customers cu"+h+"ON cu.customer_id=v.customer_id WHERE v.booking_code=? OR TRY_CONVERT(BIGINT,?)=v.reservation_id";try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,id);p.setString(2,id);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();long rid=r.getLong(1);return Optional.of(new CheckInDto(rid,r.getString(2),r.getString(3),r.getLong(4),r.getString(5),r.getBoolean(6),r.getObject(7,LocalDate.class),r.getObject(8,LocalDate.class),r.getBoolean(9),r.getBoolean(10),r.getBigDecimal(11),r.getBigDecimal(12),guests(c,rid),selections(c,rid),r.getInt(13)));}}}
 public List<ReservationSearchDto> searchReservations(Connection c,String keyword)throws SQLException{String q="SELECT TOP 30 v.reservation_id,v.booking_code,cu.full_name,cu.phone,cu.email,v.check_in_date,v.check_out_date,v.status_code FROM reservations v JOIN customers cu ON cu.customer_id=v.customer_id WHERE v.booking_code LIKE ? OR cu.full_name LIKE ? OR cu.phone LIKE ? OR cu.email LIKE ? OR cu.id_document_number LIKE ? ORDER BY CASE WHEN v.status_code='CONFIRMED' THEN 0 ELSE 1 END,v.check_in_date DESC,v.reservation_id DESC";List<ReservationSearchDto>x=new ArrayList<>();String like="%"+keyword+"%";try(PreparedStatement p=c.prepareStatement(q)){for(int i=1;i<=5;i++)p.setString(i,like);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new ReservationSearchDto(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getObject(6,LocalDate.class),r.getObject(7,LocalDate.class),r.getString(8)));}}return x;}
 private List<StayingGuestDto> guests(Connection c,long rid)throws SQLException{List<StayingGuestDto>x=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT reservation_guest_id,full_name,date_of_birth,id_document_type,id_document_number,nationality,is_primary_guest FROM reservation_guests WHERE reservation_id=? ORDER BY is_primary_guest DESC,reservation_guest_id")){p.setLong(1,rid);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new StayingGuestDto(r.getLong(1),r.getString(2),r.getObject(3,LocalDate.class),r.getString(4),r.getString(5),r.getString(6),r.getBoolean(7)));}}return x;}
 private List<RoomSelectionDto> selections(Connection c,long rid)throws SQLException{List<RoomSelectionDto>x=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT rr.reservation_room_id,rr.room_type_id,rt.type_name,rr.quantity FROM reservation_rooms rr JOIN room_types rt ON rt.room_type_id=rr.room_type_id WHERE rr.reservation_id=? ORDER BY rr.reservation_room_id")){p.setLong(1,rid);try(ResultSet r=p.executeQuery()){while(r.next()){long rr=r.getLong(1);x.add(new RoomSelectionDto(rr,r.getLong(2),r.getString(3),r.getInt(4),findAvailableRooms(c,rr)));}}}return x;}
 public int markCheckedIn(Connection c,long id,long user)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE reservations SET status_code='CHECKED_IN',actual_check_in_at=SYSUTCDATETIME(),checked_in_by_user_id=?,updated_at=SYSUTCDATETIME() WHERE reservation_id=? AND status_code='CONFIRMED'")){p.setLong(1,user);p.setLong(2,id);return p.executeUpdate();}}
 public void ensureDraftInvoice(Connection c,long id)throws SQLException{String q="IF NOT EXISTS(SELECT 1 FROM invoices WITH (UPDLOCK,HOLDLOCK) WHERE reservation_id=?) INSERT INTO invoices(reservation_id,customer_id,invoice_number,issued_by_user_id,issued_at,currency_code,subtotal,tax_amount,total_amount,paid_amount,status_code) SELECT v.reservation_id,v.customer_id,CONCAT('INV-',v.reservation_id),NULL,NULL,h.currency_code,0,0,0,0,'DRAFT' FROM reservations v CROSS JOIN hotel_profile h WHERE v.reservation_id=? AND h.profile_id=1";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);p.setLong(2,id);p.executeUpdate();}}
 public Optional<RoomChangeDto> findRoomChange(Connection c,long id,boolean lock)throws SQLException{String h=lock?" WITH (UPDLOCK,HOLDLOCK) ":" ";String q="SELECT a.room_assignment_id,v.reservation_id,rr.reservation_room_id,v.booking_code,cu.full_name,v.status_code,v.check_in_date,v.check_out_date,rr.room_type_id,rt.type_name,rm.room_id,rm.room_number,rm.floor_number,a.assigned_at FROM room_assignments a"+h+"JOIN reservation_rooms rr"+h+"ON rr.reservation_room_id=a.reservation_room_id JOIN reservations v"+h+"ON v.reservation_id=rr.reservation_id JOIN customers cu ON cu.customer_id=v.customer_id JOIN room_types rt ON rt.room_type_id=rr.room_type_id JOIN rooms rm ON rm.room_id=a.room_id WHERE a.room_assignment_id=? AND a.is_current=1 AND a.unassigned_at IS NULL";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();Number f=(Number)r.getObject(13);return Optional.of(new RoomChangeDto(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getObject(7,LocalDate.class),r.getObject(8,LocalDate.class),r.getLong(9),r.getString(10),r.getLong(11),r.getString(12),f==null?null:f.intValue(),r.getObject(14,LocalDateTime.class)));}}}
 public int closeAssignment(Connection c,long id,String reason)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE room_assignments SET is_current=0,unassigned_at=SYSUTCDATETIME(),unassigned_reason=? WHERE room_assignment_id=? AND is_current=1 AND unassigned_at IS NULL")){p.setNString(1,reason);p.setLong(2,id);return p.executeUpdate();}}
 public int updateRoomStatus(Connection c,long id,String op,String clean)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE rooms SET operational_status=?,cleaning_status=?,updated_at=SYSUTCDATETIME() WHERE room_id=?")){p.setString(1,op);p.setString(2,clean);p.setLong(3,id);return p.executeUpdate();}}
 public List<AssignmentHistoryDto> findHistory(Connection c,String id)throws SQLException{String q="SELECT TOP 100 a.room_assignment_id,v.reservation_id,rr.reservation_room_id,v.booking_code,cu.full_name,v.status_code,rt.type_name,rm.room_number,rm.floor_number,COALESCE(u.full_name,N'Hệ thống'),a.assigned_at,a.unassigned_at,a.unassigned_reason,a.is_current FROM room_assignments a JOIN reservation_rooms rr ON rr.reservation_room_id=a.reservation_room_id JOIN reservations v ON v.reservation_id=rr.reservation_id JOIN customers cu ON cu.customer_id=v.customer_id JOIN rooms rm ON rm.room_id=a.room_id JOIN room_types rt ON rt.room_type_id=rm.room_type_id LEFT JOIN dbo.[users] u ON u.user_id=a.assigned_by_user_id WHERE ? IS NULL OR v.booking_code LIKE ? OR cu.full_name LIKE ? OR cu.phone LIKE ? OR rm.room_number LIKE ? ORDER BY a.assigned_at DESC,a.room_assignment_id DESC";List<AssignmentHistoryDto>x=new ArrayList<>();try(PreparedStatement p=c.prepareStatement(q)){String like=id==null?null:"%"+id+"%";p.setString(1,id);for(int i=2;i<=5;i++)p.setString(i,like);try(ResultSet r=p.executeQuery()){while(r.next()){Number f=(Number)r.getObject(9);Timestamp un=r.getTimestamp(12);x.add(new AssignmentHistoryDto(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),f==null?null:f.intValue(),r.getString(10),r.getTimestamp(11).toLocalDateTime(),un==null?null:un.toLocalDateTime(),r.getString(13),r.getBoolean(14)));}}return x;}
}
}
